import json, re, unicodedata, hashlib
d=json.load(open("prazos.json",encoding="utf-8"))
c,s=d["citacao"],d["sentenca"]
print("FUNDAMENTO citacao:\n"+c["fundamento"]+"\n---")
need_c={"disponibilizacao","publicacao","inicio_contagem","contestacao_vencimento","prazo_em_dobro","fundamento"}
need_s={"disponibilizacao","publicacao","inicio_contagem","embargos_vencimento","apelacao_vencimento","dias_suspensos_ou_feriados_considerados"}
assert need_c<=set(c) and need_s<=set(s)
assert c["prazo_em_dobro"] is False
exp_c={"disponibilizacao":"2026-11-19","publicacao":"2026-11-23","inicio_contagem":"2026-11-24","contestacao_vencimento":"2026-12-15"}
exp_s={"disponibilizacao":"2026-12-10","publicacao":"2026-12-11","inicio_contagem":"2026-12-14","embargos_vencimento":"2026-12-18","apelacao_vencimento":"2027-02-03"}
for k,v in exp_c.items(): assert c[k]==v,(k,c[k])
for k,v in exp_s.items(): assert s[k]==v,(k,s[k])
ds=s["dias_suspensos_ou_feriados_considerados"]
assert len(ds)==23 and all(re.fullmatch(r"\d{4}-\d{2}-\d{2}",x) for x in ds)
assert "U1-U5" in c["fundamento"] and "24/10/2026" in c["fundamento"] and "15/12/2026 é a data de trabalho segura" in c["fundamento"]
raw=json.dumps(d,ensure_ascii=False)
for stale in ["2026-12-16","2027-02-04"]: assert stale not in raw, stale
assert "{{" not in raw and "TODO" not in raw.upper()
print("prazos.json OK  md5", hashlib.md5(open("prazos.json","rb").read()).hexdigest())
for fn in ["memoria.md","QUESTIONS.md","PERGUNTAS.md","STATUS.md"]:
    t=open(fn,encoding="utf-8").read()
    assert "{{" not in t and "TODO" not in t.upper(), fn
    assert not [ch for ch in t if unicodedata.east_asian_width(ch) in "WF"], fn
    print(fn,"OK bytes",len(t.encode()),"md5",hashlib.md5(t.encode()).hexdigest())
m=open("memoria.md",encoding="utf-8").read()
for probe in ["### 9.1 Incógnitas sinalizadas","15/02/2027 (segunda","U1","U2","U3","U4","U5","§ 6.4","05/02/2027","15/12/2026","03/02/2027","art. 229, § 2º"]:
    assert probe in m, probe
q=open("QUESTIONS.md",encoding="utf-8").read(); p=open("PERGUNTAS.md",encoding="utf-8").read()
assert q==p
for probe in ["U1","U2","U3","U4","U5","24/10/2026","15/02/2027"]:
    assert probe in q, probe
st=open("STATUS.md",encoding="utf-8").read()
for probe in ["COMPLETE WITH OPEN ITEMS","Resposta do cliente (24/10/2026)","U1","U5","15/02/2027","prazo_em_dobro: false"]:
    assert probe in st, probe
lib=set(mm.group(0) for mm in re.finditer(r"library/[A-Za-z0-9_\-.]+\.md", m))
allowed={"library/cpc_prazos.md","library/cpc_prazos_recursais.md","library/lei11419_art4.md","library/calendario_forense_campinas.md"}
assert lib<=allowed, lib-allowed
print("citações biblioteca:", sorted(lib))
import sys; sys.path.insert(0,"/work/workspace")
import calculo_prazos as cp; cp.conferir()
print("conferir() OK — TUDO VERIFICADO")
PY

